"""Render buildless GitHub Pages documents. No dependencies or private app data."""
from pathlib import Path
from html import escape

ROOT = Path(__file__).parent
DOCS = ROOT / "docs"
BASE = "https://draknorixdev.github.io/tempon-site/"
EMAIL = "draknorix.dev@gmail.com"
