def shell(title, description, body, filename, active=""):
    nav = [("index.html", "TEMPON"), ("beta.html", "Kapalı beta"), ("destek.html", "Destek"), ("gizlilik.html", "Gizlilik")]
    links = "".join(f'<a href="{url}"' + (' aria-current="page"' if url == active else '') + f'>{label}</a>' for url, label in nav)
    return f'''<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>{escape(title)} — TEMPON · DrakNorix</title><meta name="description" content="{escape(description, quote=True)}">
<meta name="theme-color" content="#507600"><meta name="referrer" content="strict-origin-when-cross-origin">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'self'; img-src 'self' data:; base-uri 'self'; form-action 'none'">
<link rel="canonical" href="{BASE}{filename}"><link rel="icon" href="assets/logo.svg" type="image/svg+xml"><link rel="stylesheet" href="assets/site.css">
<meta property="og:title" content="{escape(title, quote=True)} · TEMPON"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE}{filename}">
</head><body><a class="skip" href="#icerik">İçeriğe geç</a>
<header><div class="wrap nav"><a class="brand" href="index.html"><img src="assets/logo.svg" alt="" width="43" height="43"><span>TEMPON<small>DRAKNORIX</small></span></a><nav class="nav-links" aria-label="Ana menü">{links}</nav></div></header>
<main id="icerik" class="wrap">{body}</main>
<footer><div class="wrap"><div class="footer-top"><div><a class="brand" href="index.html">TEMPON</a><span class="quiet">Kurye gününün kişisel kaydı.</span></div><nav class="footer-links" aria-label="Politikalar ve iletişim"><a href="gizlilik.html">Gizlilik politikası</a><a href="veri-silme.html">Verilerini sil</a><a href="kullanim-kosullari.html">Kullanım koşulları</a><a href="destek.html">Destek</a><a href="beta.html">Kapalı beta</a></nav></div><p class="footer-meta">© 2026 DrakNorix · <a href="mailto:{EMAIL}">{EMAIL}</a><br>TEMPON bağımsız bir kurye takip uygulamasıdır. Getir veya Getir MDU tarafından sunulmaz ya da onaylanmış olduğu iddia edilmez.</p></div></footer>
</body></html>'''

def heading(kicker, title, lead):
    return f'<div class="page-heading"><span class="eyebrow">{kicker}</span><h1>{title}</h1><p class="lead">{lead}</p></div>'

def document(title, lead, sections):
    toc = ''.join(f'<a href="#{key}">{name}</a>' for key, name, _ in sections)
    body = ''.join(f'<section id="{key}"><h2>{name}</h2>{content}</section>' for key, name, content in sections)
    return heading('TEMPON · DrakNorix', title, lead) + f'<div class="document"><aside class="toc" aria-label="Sayfa içeriği"><strong>BU SAYFADA</strong>{toc}</aside><article class="prose">{body}</article></div>'

